{
  "iteration": 5,
  "pcvs": [
    {
      "name": "query_rows",
      "expression": "query.shape[0]",
      "rationale": "Observes the query tensor's native row count directly rather than combining metadata counts."
    },
    {
      "name": "total_context_tokens",
      "expression": "0 if attn_metadata is None else int(attn_metadata.seq_lens.sum().item())",
      "rationale": "Measures actual aggregate context length across the bounded batch, including unequal request lengths."
    },
    {
      "name": "context_blocks",
      "expression": "0 if attn_metadata is None else sum((int(length) + 31) // 32 for length in attn_metadata.seq_lens.tolist())",
      "rationale": "Counts actual KV blocks across at most eight requests instead of multiplying a maximum by batch size."
    },
    {
      "name": "scheduler_bytes",
      "expression": "0 if attn_metadata is None or attn_metadata.scheduler_metadata is None else attn_metadata.scheduler_metadata.numel() * attn_metadata.scheduler_metadata.element_size()",
      "rationale": "Tests whether scheduler metadata size captures native task partitioning missing from token-based predictors."
    }
  ],
  "hypothesis": "Repeated underprediction warrants testing native tensor dimensions, actual ragged context lengths, and scheduler metadata size. The context reductions remain small because this workload bounds batches to eight requests."
}
